<?php

declare(strict_types=1);

namespace App\Services\Providers;

use App\Contracts\VideoProviderInterface;
use App\DTOs\VideoRenderResult;
use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Str;

class ReplayVideoProvider implements VideoProviderInterface
{
  /**
   * Minimal authentic valid 1-second H.264 MP4 fixture in base64.
   */
  private const DEFAULT_MP4_BASE64 = '';
  private const CACHE_TTL_SECONDS = 3600;
  public const DEFAULT_INITIAL_PROGRESS = 40;

  private array $pollCounts = [];

  public function __construct(
    private readonly int $pendingPolls = 1,
  )
  {
  }

  public function submit(string $prompt, string $keyframePath): string
  {
    $renderId = 'replay_render_' . Str::random(16);
    $this->pollCounts[$renderId] = 0;
    Cache::put("replay_render_poll_{$renderId}", 0, self::CACHE_TTL_SECONDS);

    return $renderId;
  }

  public function poll(string $renderId): VideoRenderResult
  {
    $count = $this->pollCounts[$renderId] ?? (int) Cache::get("replay_render_poll_{$renderId}", 0);
    $count++;
    $this->pollCounts[$renderId] = $count;
    Cache::put("replay_render_poll_{$renderId}", $count, self::CACHE_TTL_SECONDS);

    if ($count <= $this->pendingPolls)
    {
      $progress = (int) round(($count / ($this->pendingPolls + 1)) * 100);

      return VideoRenderResult::pending($progress > 0 ? $progress : self::DEFAULT_INITIAL_PROGRESS);
    }

    $videoBytes = base64_decode(self::DEFAULT_MP4_BASE64, true) ?: '';

    return VideoRenderResult::completed($videoBytes);
  }
}
